from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from rest_framework import status
from organizations.models import Organization, OrganizationUser

@api_view(['POST'])
@permission_classes([IsAuthenticated])
def switch_active_organization(request):
    target_org_id = request.data.get('organization_id')
    try:
        org = Organization.objects.get(id=target_org_id)
    except Organization.DoesNotExist:
        return Response({'error': 'Organization not found'}, status=status.HTTP_404_NOT_FOUND)

    # Validate that the caller has an active membership in the organization
    is_member = OrganizationUser.objects.filter(organization=org, user=request.user).exists()
    if not is_member and not request.user.is_superuser:
        return Response({'error': 'You are not a member of this organization'}, status=status.HTTP_403_FORBIDDEN)

    request.session['active_organization_id'] = org.id
    return Response({
        'status': 'switched',
        'organization_id': org.id,
        'organization_name': org.name
    })
